const items = $input.all();
const out = [];

for (const item of items) {
  const original = item.json;
  const id = Number(original.id);
  const row_number = original.row_number;
  const whatsapp = original.whatsapp;

  const rawText = original.ctx?.message_text || original.output || original.mensagem || '';
  let partes = [];

  if (typeof rawText === 'string') {
    try {
      const parsed = JSON.parse(rawText);
      if (parsed && Array.isArray(parsed.messages)) {
        partes = parsed.messages.map(p => String(p).trim()).filter(Boolean);
      }
    } catch (e) {
      // not JSON
    }
    if (!partes.length) {
      partes = rawText.split('|').map(p => p.trim()).filter(Boolean);
    }
  }

  if (!partes.length && rawText) partes = [String(rawText).trim()];
  const total = partes.length || 1;

  partes.forEach((parte, index) => {
    out.push({
      json: {
        ...original,
        id,
        row_number,
        whatsapp,
        mensagem: parte || rawText,
        ordem: index + 1,
        total
      }
    });
  });
}

return out;

// Obtém os dados do item atual do loop
const currentItem = $input.item.json;

// Extrai informações do contexto do loop atual
const rowNumber = currentItem.row_number;
const whatsappNumber = currentItem.whatsapp;
const itemId = currentItem.id;
const evoOutput = currentItem.output;

// Função para normalizar número de WhatsApp (remove caracteres especiais)
function normalizePhone(phone) {
  if (!phone) return '';
  return String(phone).replace(/\D/g, '');
}

// Inicializa flag de erro
let hasImageError = false;
let errorDetails = null;

// Valida se existe output do EVO
if (evoOutput) {
  try {
    // Se output for string, tenta parsear como JSON
    const outputData = typeof evoOutput === 'string' ? JSON.parse(evoOutput) : evoOutput;

    // Verifica se é um array
    if (Array.isArray(outputData)) {
      // Procura por erro de imagem no array
      for (const item of outputData) {
        if (item && item.error === "Erro ao enviar imagem") {
          // Valida se o erro corresponde ao número do loop atual
          if (item.whatsapp || item.numero || item.phone) {
            const errorPhone = normalizePhone(item.whatsapp || item.numero || item.phone);
            const currentPhone = normalizePhone(whatsappNumber);

            // Confirma que o erro é do número atual
            if (errorPhone === currentPhone) {
              hasImageError = true;
              errorDetails = item;
              break;
            }
          } else {
            // Se não há identificação de número no erro, assume que é do loop atual
            hasImageError = true;
            errorDetails = item;
            break;
          }
        }
      }
    } else if (outputData && outputData.error === "Erro ao enviar imagem") {
      // Caso seja objeto único
      hasImageError = true;
      errorDetails = outputData;
    }
  } catch (e) {
    // Se houver erro no parse, verifica se a string contém o erro
    if (typeof evoOutput === 'string' && evoOutput.includes("Erro ao enviar imagem")) {
      hasImageError = true;
      errorDetails = { error: "Erro ao enviar imagem", raw: evoOutput };
    }
  }
}

// Prepara o retorno
if (hasImageError) {
  // Erro válido encontrado para o número do loop atual
  return {
    json: {
      has_error: true,
      error_type: "image_send_failure",
      row_number: rowNumber,
      whatsapp: whatsappNumber,
      id: itemId,
      error_message: "Erro ao enviar imagem",
      error_details: errorDetails,
      timestamp: new Date().toISOString(),
      loop_processed: true,
      // Dados prontos para atualizar a planilha
      spreadsheet_update: {
        row: rowNumber,
        status: "ERRO",
        error_reason: "Falha no envio de imagem",
        whatsapp_number: whatsappNumber,
        processed_at: new Date().toISOString()
      }
    }
  };
} else {
  // Nenhum erro ou erro não corresponde ao loop atual
  return {
    json: {
      has_error: false,
      row_number: rowNumber,
      whatsapp: whatsappNumber,
      id: itemId,
      loop_processed: true,
      message: "Nenhum erro de imagem detectado para este número"
    }
  };
}

// Obtém dados do item atual
const currentItem = $input.item.json;

const rowNumber = currentItem.row_number;
const whatsappNumber = currentItem.whatsapp;
const itemId = currentItem.id;

// Usa o output do próprio item
const evoOutput = currentItem.output || currentItem;

function normalizePhone(phone) {
  if (!phone) return '';
  return String(phone).replace(/\D/g, '');
}

let hasSuccess = false;
let successDetails = null;
let errorMessage = null;

if (evoOutput) {
  try {
    const outputData = typeof evoOutput === 'string' ? JSON.parse(evoOutput) : evoOutput;
    if (Array.isArray(outputData)) {
      for (const item of outputData) {
        if (item?.success === true && item.data) {
          if (item.data.key?.remoteJid) {
            const successPhone = normalizePhone(item.data.key.remoteJid);
            const currentPhone = normalizePhone(whatsappNumber);
            if (successPhone === currentPhone || successPhone.includes(currentPhone)) {
              hasSuccess = true;
              successDetails = item;
              break;
            }
          } else {
            hasSuccess = true;
            successDetails = item;
            break;
          }
        }
        if (item?.error) {
          errorMessage = item.error;
        }
      }
    } else if (outputData?.success === true && outputData.data) {
      hasSuccess = true;
      successDetails = outputData;
    } else if (outputData?.error) {
      errorMessage = outputData.error;
    }
  } catch (e) {
    if (typeof evoOutput === 'string' && evoOutput.includes('Erro')) {
      errorMessage = evoOutput;
    }
  }
}

const providerMessageId = successDetails?.data?.key?.id || null;

return {
  json: {
    has_success: hasSuccess,
    send_status: hasSuccess ? 'SENT' : 'FAILED',
    send_error: hasSuccess ? null : (errorMessage || 'Envio não confirmado'),
    provider_message_id: providerMessageId,
    row_number: rowNumber,
    whatsapp: whatsappNumber,
    id: itemId,
    loop_processed: true,
    success_details: successDetails || null
  }
};

const items = $input.all();
const results = [];
for (const item of items) {
    const json = item.json;
    let phone = '';
    let instance = 'PR2';
    let origin = 'unknown';

    if (json.body && json.body.key && json.body.key.remoteJid) {
        phone = json.body.key.remoteJid;
        instance = json.instance || 'PR2';
        origin = 'inbound';
    } else if (json.whatsapp) {
        phone = json.whatsapp.toString();
        origin = 'outbound';
    } else if (json.remoteJid) {
        phone = json.remoteJid;
        origin = 'inbound_processed';
    }

    let cleanPhone = phone.replace(/\D/g, '');
    if (cleanPhone.length === 11 && !cleanPhone.startsWith('55')) cleanPhone = '55' + cleanPhone;

    const conversation_id = `${instance}_${cleanPhone}`;
    results.push({ json: { ...json, conversation_id, flow_origin: origin } });
}
return results;

const crypto = require('crypto');
const items = $input.all();
const results = [];
for (const item of items) {
    const text = item.json.output || item.json.text || '';
    const hash = crypto.createHash('md5').update(text).digest('hex');
    results.push({ json: { ...item.json, msg_hash: hash } });
}
return results;

